    CREATE TABLE IF NOT EXISTS usuarios (id_usuario serial PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, rol text NOT NULL CHECK(rol IN ('administrador','consulta')));
    CREATE TABLE IF NOT EXISTS cargas (id_carga serial PRIMARY KEY, archivo text NOT NULL, fecha_carga timestamptz DEFAULT now(), id_usuario integer REFERENCES usuarios, filas_leidas integer NOT NULL, filas_cargadas integer NOT NULL, filas_rechazadas integer NOT NULL, CHECK(filas_leidas=filas_cargadas+filas_rechazadas));
    CREATE TABLE IF NOT EXISTS rechazos (id_rechazo serial PRIMARY KEY,id_carga integer NOT NULL REFERENCES cargas, fila_origen integer NOT NULL, motivo text NOT NULL, contenido_fila jsonb NOT NULL);
    CREATE TABLE IF NOT EXISTS rutas (cod_ruta text PRIMARY KEY,nombre text NOT NULL,km_recorrido numeric NOT NULL CHECK(km_recorrido>=0),buses_asignados integer NOT NULL CHECK(buses_asignados>=0),id_carga integer NOT NULL REFERENCES cargas);
    CREATE TABLE IF NOT EXISTS estaciones (cod_estacion text PRIMARY KEY,estacion text NOT NULL,ruta text NOT NULL REFERENCES rutas,tiene_cajero boolean NOT NULL,id_carga integer NOT NULL REFERENCES cargas);
    CREATE TABLE IF NOT EXISTS franjas (franja text PRIMARY KEY,hora_inicio time NOT NULL,hora_fin time NOT NULL);
    INSERT INTO franjas VALUES ('Pico mañana','05:00','08:00'),('Valle','08:00','17:00'),('Pico tarde','17:00','19:00'),('Noche','19:00','22:00') ON CONFLICT DO NOTHING;
    CREATE TABLE IF NOT EXISTS validaciones (id_validacion serial PRIMARY KEY,fecha_hora timestamp NOT NULL CHECK(fecha_hora >= '2025-11-01' AND fecha_hora < '2026-11-01'),hora_conocida boolean NOT NULL,cod_estacion text NOT NULL REFERENCES estaciones,id_tarjeta text NOT NULL,tipo_tarjeta text NOT NULL CHECK(tipo_tarjeta IN ('General','Estudiante','Adulto mayor')),valor_pasaje numeric NOT NULL CHECK(valor_pasaje>=0),id_carga integer NOT NULL REFERENCES cargas, UNIQUE(fecha_hora,hora_conocida,cod_estacion,id_tarjeta,tipo_tarjeta,valor_pasaje));
    CREATE TABLE IF NOT EXISTS despachos (id_despacho serial PRIMARY KEY,fecha date NOT NULL CHECK(fecha BETWEEN '2025-11-01' AND '2026-10-31'),cod_ruta text NOT NULL REFERENCES rutas,franja text NOT NULL REFERENCES franjas,despachos_programados integer NOT NULL CHECK(despachos_programados>=0),despachos_realizados integer NOT NULL CHECK(despachos_realizados BETWEEN 0 AND despachos_programados),id_carga integer NOT NULL REFERENCES cargas,UNIQUE(fecha,cod_ruta,franja));
    CREATE OR REPLACE VIEW archivo_carga AS SELECT * FROM cargas;
    CREATE OR REPLACE VIEW fila_rechazada AS SELECT * FROM rechazos;
